#!/usr/bin/env node
/* 小青囊 Node.js 后台服务。保留现有接口路径、SQLite 数据和后台页面。 */
import http from 'node:http'
import fs from 'node:fs'
import path from 'node:path'
import crypto from 'node:crypto'
import { execFileSync } from 'node:child_process'
import os from 'node:os'
import { fileURLToPath } from 'node:url'
import { DatabaseSync } from 'node:sqlite'
import { URL } from 'node:url'

const ROOT = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '..')
const WEB_DIR = path.join(ROOT, 'unpackage', 'dist', 'build', 'web')
const RUNTIME_DIR = path.join(ROOT, '.runtime')
const DATABASE_FILE = process.env.XQN_DATABASE_FILE || path.join(RUNTIME_DIR, 'content.db')
const UPLOAD_DIR = process.env.XQN_UPLOAD_DIR || path.join(RUNTIME_DIR, 'uploads')
const SCHEMA_FILE = path.join(ROOT, 'database', 'schema.sql')
const PORT = Number(process.env.XQN_PORT || 4173)
const SOURCE_API_BASE = String(process.env.XQN_ZIBINGZIYI_API || process.env.XQN_SOURCE_API || '').replace(/\/+$/, '')
const SESSION_COOKIE = 'xqn_admin_session'
const SESSION_SECONDS = 12 * 60 * 60
const MAX_BODY = 2 * 1024 * 1024
const MAX_UPLOAD = 120 * 1024 * 1024
const BANNED = ['治疗', '根治', '治愈', '疗效', '诊断', '处方', '患者', '治好了', '疾病调理', '包治', '药到病除', '立刻见效', '永不复发']
const AREAS = new Set(['head', 'occiput', 'forehead', 'temple', 'eye', 'ear', 'cheek', 'nose', 'mouth', 'jaw', 'neck', 'shoulder', 'chest', 'breast', 'nipple-areola', 'abdomen', 'pelvis', 'upper-back', 'lower-back', 'buttocks', 'upper-arm', 'elbow', 'forearm', 'hand', 'thigh', 'knee', 'lower-leg', 'foot', 'vulva', 'penis', 'scrotum', 'perineum', 'anus', 'whole'])
const AREA_MAP = { 腰部: 'lower-back', 腰骶部: 'lower-back', 后腰: 'lower-back', 腰: 'lower-back', 腹部: 'abdomen', 肚子: 'abdomen', 足底: 'foot', 脚: 'foot', 头部: 'head', 头面部: 'head', 颈部: 'neck', 肩部: 'shoulder', 全身: 'whole' }
const PERMISSIONS = [
  ['methods.read', '查看方法库', '基础数据库', 10], ['methods.write', '编辑方法库', '基础数据库', 20], ['methods.publish', '发布方法', '基础数据库', 30],
  ['problems.read', '查看问题库', '基础数据库', 40], ['problems.write', '编辑问题库', '基础数据库', 50], ['points.read', '查看穴位库', '基础数据库', 60], ['points.write', '编辑穴位库', '基础数据库', 70],
  ['articles.read', '查看文章管理', '青囊文集', 100], ['articles.write', '编辑文章', '青囊文集', 110], ['articles.publish', '发布文章', '青囊文集', 120], ['columns.manage', '管理专栏', '青囊文集', 130], ['source.manage', '来源同步与审核', '青囊文集', 140],
  ['backup.export', '导出备份', '系统工具', 300], ['logs.read', '查看操作记录', '系统工具', 310], ['permissions.manage', '管理管理员权限', '系统工具', 320]
]
const MIME = { '.html': 'text/html; charset=utf-8', '.js': 'text/javascript; charset=utf-8', '.css': 'text/css; charset=utf-8', '.json': 'application/json; charset=utf-8', '.svg': 'image/svg+xml', '.png': 'image/png', '.jpg': 'image/jpeg', '.jpeg': 'image/jpeg', '.gif': 'image/gif', '.webp': 'image/webp', '.mp4': 'video/mp4' }
const now = () => Date.now()
const asText = value => String(value ?? '').trim()
const json = value => JSON.stringify(value)
const sha256 = value => crypto.createHash('sha256').update(String(value)).digest('hex')
const random = bytes => crypto.randomBytes(bytes).toString('base64url')
const splitValues = value => Array.isArray(value) ? value.map(asText).filter(Boolean) : asText(value).split(/[\n,，;；]+/).map(item => item.trim()).filter(Boolean)
const rows = values => values.map(row => Object.fromEntries(Object.entries(row)))
function dbOpen() { fs.mkdirSync(path.dirname(DATABASE_FILE), { recursive: true }); const database = new DatabaseSync(DATABASE_FILE); database.exec('PRAGMA foreign_keys=ON; PRAGMA journal_mode=WAL;'); return database }
function closeDb(database) { try { database.close() } catch {} }
function one(database, sql, params = []) { return database.prepare(sql).get(...params) }
function all(database, sql, params = []) { return rows(database.prepare(sql).all(...params)) }
function run(database, sql, params = []) { return database.prepare(sql).run(...params) }

function initialize() {
  const database = dbOpen()
  try {
    database.exec(fs.readFileSync(SCHEMA_FILE, 'utf8'))
    const stamp = now()
    for (const [code, label, group, order] of PERMISSIONS) run(database, 'INSERT OR REPLACE INTO admin_permission_catalog(code,label,permission_group,sort_order) VALUES(?,?,?,?)', [code, label, group, order])
    all(database, 'SELECT id FROM admin_users ORDER BY created_at,id').forEach((user, index) => run(database, 'INSERT OR IGNORE INTO admin_user_access(user_id,account_type,created_at,updated_at) VALUES(?,?,?,?)', [user.id, index === 0 ? 'super_admin' : 'admin', stamp, stamp]))
    run(database, 'DELETE FROM admin_sessions WHERE expires_at < ?', [stamp])
  } finally { closeDb(database) }
}

function hashPassword(password, salt) { return crypto.pbkdf2Sync(String(password), Buffer.from(salt, 'hex'), 310000, 32, 'sha256').toString('hex') }
function cookiesFrom(request) { return Object.fromEntries((request.headers.cookie || '').split(';').map(item => item.trim().split('=').map(decodeURIComponent)).filter(item => item.length === 2)) }
function setCookie(response, name, value, maxAge = SESSION_SECONDS) { response.setHeader('Set-Cookie', `${name}=${encodeURIComponent(value)}; Path=/; HttpOnly; SameSite=Strict; Max-Age=${maxAge}${process.env.NODE_ENV === 'production' ? '; Secure' : ''}`) }
function send(response, status, payload, headers = {}) { const body = Buffer.from(JSON.stringify(payload)); response.writeHead(status, { 'Content-Type': 'application/json; charset=utf-8', 'Content-Length': body.length, ...headers }); response.end(body) }
function readBody(request, limit = MAX_BODY) { return new Promise((resolve, reject) => { const chunks = []; let total = 0; request.on('data', chunk => { total += chunk.length; if (total > limit) { reject(new Error('请求内容过大')); request.destroy() } else chunks.push(chunk) }); request.on('end', () => resolve(Buffer.concat(chunks))); request.on('error', reject) }) }
async function readJson(request) { const body = await readBody(request); if (!body.length) throw new Error('请求内容为空'); return JSON.parse(body.toString('utf8')) }

function stripTags(value) { return String(value || '').replace(/<[^>]*>/g, ' ').replace(/&nbsp;/g, ' ').replace(/&amp;/g, '&').replace(/&lt;/g, '<').replace(/&gt;/g, '>').trim() }
function escapeHtml(value) { return String(value ?? '').replace(/[&<>"']/g, character => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[character])) }
function sanitizeHtml(value) { return String(value || '').replace(/<(script|style|iframe|object|embed|form)\b[\s\S]*?<\/\1\s*>/gi, '').replace(/\son\w+\s*=\s*(?:"[^"]*"|'[^']*'|[^\s>]+)/gi, '').replace(/\s(href|src)\s*=\s*(["'])\s*javascript:[\s\S]*?\2/gi, '').trim() }
const promotionPattern = /报名方式|报名客服|付费报名|交费报名|联系客服|详询客服|扫码.{0,20}(报名|购买|付款)|扫.{0,20}二维码.{0,20}(报名|交费)|长按.{0,20}二维码.{0,20}(报名|购买|付款)|微信号[：:]|微信号码|收费课程|付费培训|限量招募|名额有限|拉微信群|微店.{0,20}(下单|购买)/i
function cleanImportedHtml(source) { let html = String(source || ''), removed = [], flags = []; html = html.replace(/<(p|h[1-6]|li)\b[^>]*>[\s\S]*?<\/\1\s*>/gi, block => { const plain = stripTags(block); if (!promotionPattern.test(plain)) return block; if (plain.length > 500) { flags.push('含商业内容，需人工复核'); return block } removed.push(plain); flags.push('已移除明确商业段落'); return '' }); if (/(二维码|报名|购买|付款|微店|课程)/.test(stripTags(html))) flags.push('推广附近图片需人工确认'); return { html, removed, flags: [...new Set(flags)] } }
function summaryFrom(plain) { const text = String(plain || '').replace(/\s+/g, ' ').trim(); return text.length > 108 ? `${text.slice(0, 106)}…` : text }
function extractDocx(buffer, originalName) { const tempDir = fs.mkdtempSync(path.join(os.tmpdir(), 'xqn-docx-')), archive = path.join(tempDir, 'article.docx'); fs.writeFileSync(archive, buffer); try { const xml = execFileSync('unzip', ['-p', archive, 'word/document.xml'], { encoding: 'utf8', maxBuffer: MAX_UPLOAD }); const paragraphs = [...xml.matchAll(/<w:p\b[\s\S]*?<\/w:p>/g)].map(match => [...match[0].matchAll(/<w:t\b[^>]*>([\s\S]*?)<\/w:t>/g)].map(item => item[1]).join('')).map(text => text.replace(/&amp;/g, '&').replace(/&lt;/g, '<').replace(/&gt;/g, '>').replace(/&#39;/g, "'").replace(/&quot;/g, '"').trim()).filter(Boolean); let html = paragraphs.map((text, index) => `<${index === 0 ? 'h2' : 'p'}>${escapeHtml(text)}</${index === 0 ? 'h2' : 'p'}>`).join(''); const media = execFileSync('unzip', ['-Z1', archive], { encoding: 'utf8' }).split(/\r?\n/).filter(name => /^word\/media\//i.test(name)); for (const member of media) { const data = execFileSync('unzip', ['-p', archive, member], { maxBuffer: MAX_UPLOAD }); const suffix = path.extname(member).toLowerCase() || '.png'; const filename = `anth-${sha256(data).slice(0, 20)}${suffix}`; const destination = path.join(UPLOAD_DIR, filename); fs.mkdirSync(UPLOAD_DIR, { recursive: true }); if (!fs.existsSync(destination)) fs.writeFileSync(destination, data); html += `<img src="/media/${filename}" alt="${escapeHtml(path.basename(originalName, path.extname(originalName)))}配图">` } return { html, plain: stripTags(html) } } finally { fs.rmSync(tempDir, { recursive: true, force: true }) } }
function normalizeContent(input = {}) { const value = { ...input, type: input.type === 'article' ? 'article' : 'skill' }; value.id = asText(value.id); value.title = asText(value.title); value.summary = asText(value.summary); value.keywords = asText(value.keywords); value.contentHtml = sanitizeHtml(value.contentHtml || value.methodContentHtml); value.casesHtml = sanitizeHtml(value.casesHtml); value.bodyAreaIds = [...new Set(splitValues(value.bodyAreaIds || value.bodyArea).map(item => AREAS.has(item) ? item : AREA_MAP[item]).filter(Boolean))]; value.accessLevel = value.accessLevel === 'subscription' ? 'subscription' : 'free'; for (const key of ['methodName', 'methodType', 'materials', 'usageScope', 'notices', 'outsideScope', 'helpConditions', 'columnId', 'columnName', 'issueNumber', 'topics', 'coverImage', 'editorNote', 'sourceKind', 'sourceArticleId', 'reviewStatus', 'sourceTitle', 'sourceAuthor', 'sourcePlatform', 'sourceUrl', 'sourceText', 'sourceNotes']) value[key] = asText(value[key]); value.pointLinks = Array.isArray(input.pointLinks) ? input.pointLinks : []; value.problemLinks = Array.isArray(input.problemLinks) ? input.problemLinks : []; return value }
function normalizePoint(input = {}) { const value = { ...input }; for (const key of ['id', 'name', 'bodyAreaId', 'professionalLocation', 'everydayLocation', 'commonMistakes', 'notices', 'sourceTitle', 'sourceText', 'sourceNotes']) value[key] = asText(value[key]); value.aliases = splitValues(value.aliases); value.contentHtml = sanitizeHtml(value.contentHtml); return value }
function normalizeProblem(input = {}) { const value = { ...input }; for (const key of ['id', 'name', 'description', 'notes', 'needAsk', 'dangerNotice']) value[key] = asText(value[key]); value.aliases = splitValues(value.aliases); value.bodyAreaIds = [...new Set(splitValues(value.bodyAreaIds).filter(item => AREAS.has(item)))]; value.methodLinks = Array.isArray(input.methodLinks) ? input.methodLinks : []; return value }
function validateContent(content) { const required = ['id', 'type', 'title', 'contentHtml', 'sourceTitle', 'sourceText']; if (content.type === 'skill') required.push('methodName', 'methodType', 'materials', 'usageScope', 'outsideScope', 'helpConditions'); const missing = required.filter(key => !asText(content[key])); if (!['article', 'skill'].includes(content.type)) missing.push('type'); if (content.type === 'skill' && !content.bodyAreaIds.length) missing.push('bodyAreaIds'); if (!stripTags(content.contentHtml)) missing.push('contentHtml'); if (content.type === 'skill' && BANNED.some(word => [content.title, content.summary, stripTags(content.contentHtml), content.usageScope, content.notices, content.outsideScope, content.helpConditions, stripTags(content.casesHtml)].join(' ').includes(word))) missing.push('compliance'); return [...new Set(missing)] }
function validatePoint(point) { return [...new Set(['id', 'name', 'bodyAreaId', 'professionalLocation', 'everydayLocation', 'contentHtml', 'sourceTitle', 'sourceText'].filter(key => !asText(point[key])).concat(AREAS.has(point.bodyAreaId) ? [] : ['bodyAreaId']))] }
function validateProblem(problem) { return [...new Set(['id', 'name'].filter(key => !asText(problem[key])).concat(problem.bodyAreaIds.length ? [] : ['bodyAreaIds']))] }

function relationPoints(database, contentId, verifiedOnly = false) { const values = all(database, `SELECT p.payload_json,p.status,l.point_id,l.sort_order,l.instruction FROM content_point_links l JOIN admin_points p ON p.id=l.point_id WHERE l.content_id=? ${verifiedOnly ? "AND p.status='verified'" : ''} ORDER BY l.sort_order,p.name`, [contentId]); return values.map(row => ({ pointId: row.point_id, order: row.sort_order, instruction: row.instruction, point: { ...normalizePoint(JSON.parse(row.payload_json)), status: row.status } })) }
function relationProblems(database, contentId, verifiedOnly = false) { const values = all(database, `SELECT p.payload_json,p.status,l.problem_id,l.sort_order,l.evidence_type,l.evidence_text FROM problem_content_links l JOIN admin_problems p ON p.id=l.problem_id WHERE l.content_id=? ${verifiedOnly ? "AND p.status='verified'" : ''} ORDER BY l.sort_order,p.name`, [contentId]); return values.map(row => ({ problemId: row.problem_id, order: row.sort_order, evidenceType: row.evidence_type, evidenceText: row.evidence_text, problem: { ...normalizeProblem(JSON.parse(row.payload_json)), status: row.status } })) }
function withRelations(database, content, verifiedOnly = false) { return { ...content, pointLinks: relationPoints(database, content.id, verifiedOnly), problemLinks: relationProblems(database, content.id, verifiedOnly) } }
function publicList(database, page = 1, pageSize = 24, contentId = '', includeBody = false) { const where = contentId ? "status='published' AND id=?" : "status='published'", args = contentId ? [contentId] : [], count = one(database, `SELECT COUNT(*) AS count FROM admin_contents WHERE ${where}`, args).count, size = Math.min(60, Math.max(1, Number(pageSize) || 24)), current = Math.max(1, Number(page) || 1), values = contentId ? all(database, `SELECT payload_json FROM admin_contents WHERE ${where} LIMIT 1`, args) : all(database, `SELECT payload_json FROM admin_contents WHERE ${where} ORDER BY published_at DESC LIMIT ? OFFSET ?`, [...args, size, (current - 1) * size]); return { values: values.map(row => normalizeContent(JSON.parse(row.payload_json))).filter(item => validateContent(item).length === 0).map(item => { if (!includeBody) { item.contentHtml = ''; item.casesHtml = ''; item.sourceText = ''; item.sourceNotes = '' } if (item.coverImage?.startsWith('https://zibingziyi.zengshiwuyu.cn/')) item.coverImage = item.coverImage.replace('https://zibingziyi.zengshiwuyu.cn/', 'https://zengshiwuyu.cn/'); return withRelations(database, item, true) }), count, size, page: current } }

function session(database, request) { const token = cookiesFrom(request)[SESSION_COOKIE]; return token ? one(database, 'SELECT s.user_id,s.csrf_token,u.username,a.account_type FROM admin_sessions s JOIN admin_users u ON u.id=s.user_id LEFT JOIN admin_user_access a ON a.user_id=u.id WHERE s.token_hash=? AND s.expires_at>?', [sha256(token), now()]) : null }
function requireSession(database, request, response, write = false, permission = '') { const current = session(database, request); if (!current) { send(response, 401, { error: '请先登录' }); return null } if (write && current.csrf_token !== (request.headers['x-csrf-token'] || '')) { send(response, 403, { error: '安全校验失败，请刷新页面后重试' }); return null } if (permission && current.account_type !== 'super_admin') { const allowed = one(database, 'SELECT enabled FROM admin_user_permissions WHERE user_id=? AND permission_code=?', [current.user_id, permission]); if (!allowed || !allowed.enabled) { send(response, 403, { error: '当前账号没有此操作权限' }); return null } } return current }
function audit(database, userId, action, entityType, entityId = null, detail = {}) { run(database, 'INSERT INTO admin_audit_logs(user_id,action,entity_type,entity_id,detail_json,created_at) VALUES(?,?,?,?,?,?)', [userId, action, entityType, entityId, json(detail), now()]) }
function issueSession(database, userId) { const token = random(32), csrf = random(24), stamp = now(); run(database, 'DELETE FROM admin_sessions WHERE user_id=? OR expires_at<?', [userId, stamp]); run(database, 'INSERT INTO admin_sessions(token_hash,user_id,csrf_token,expires_at,created_at) VALUES(?,?,?,?,?)', [sha256(token), userId, csrf, stamp + SESSION_SECONDS * 1000, stamp]); return { token, csrf } }

async function handle(request, response) {
  const url = new URL(request.url, `http://${request.headers.host || 'localhost'}`), pathname = decodeURIComponent(url.pathname)
  if (pathname.startsWith('/.runtime') || pathname.startsWith('/.git') || pathname.startsWith('/database') || pathname.startsWith('/docs') || pathname.startsWith('/scripts') || pathname === '/AGENTS.md') return send(response, 404, { error: '资源不存在' })
  const forwardedProto = String(request.headers['x-forwarded-proto'] || '').split(',')[0].trim().toLowerCase(); if (['/api/admin/', '/api/upload'].some(prefix => pathname.startsWith(prefix)) && forwardedProto && forwardedProto !== 'https') return send(response, 426, { error: '账号操作必须使用 HTTPS' })
  const database = dbOpen()
  try {
    if (pathname === '/api/published-content' && request.method === 'GET') { const result = publicList(database, url.searchParams.get('page'), url.searchParams.get('pageSize'), '', false); const columns = all(database, "SELECT id,name,description,color,sort_order,status FROM anthology_columns WHERE status='visible' ORDER BY sort_order,name"); return send(response, 200, { contents: result.values, columns, page: result.page, pageSize: result.size, total: result.count, hasMore: result.page * result.size < result.count }) }
    const publicDetail = pathname.match(/^\/api\/published-content\/([^/]+)$/); if (publicDetail && request.method === 'GET') { const result = publicList(database, 1, 1, publicDetail[1], true); if (!result.values.length) return send(response, 404, { error: '内容不存在' }); return send(response, 200, { content: result.values[0] }) }
    if (pathname === '/api/admin/bootstrap' && request.method === 'GET') { const current = session(database, request); return send(response, 200, { needsSetup: one(database, 'SELECT COUNT(*) AS count FROM admin_users').count === 0, authenticated: Boolean(current), username: current?.username || null, csrfToken: current?.csrf_token || null }) }
    if (pathname === '/api/admin/setup' && request.method === 'POST') return await setupAdmin(request, response, database)
    if (pathname === '/api/admin/login' && request.method === 'POST') return await login(request, response, database)
    if (pathname === '/api/admin/logout' && request.method === 'POST') return logout(request, response, database)
    if (pathname === '/api/admin/contents' && request.method === 'GET') return listContents(request, response, database)
    const detail = pathname.match(/^\/api\/admin\/contents\/([^/]+)$/); if (detail && request.method === 'GET') return getContent(request, response, database, detail[1])
    if (pathname === '/api/admin/contents' && request.method === 'POST') return await saveContent(request, response, database)
    const contentStatus = pathname.match(/^\/api\/admin\/contents\/([^/]+)\/(publish|withdraw|archive|restore)$/); if (contentStatus && request.method === 'POST') return changeContentStatus(request, response, database, contentStatus[1], contentStatus[2])
    if (pathname === '/api/admin/columns' && request.method === 'GET') return listColumns(request, response, database)
    if (pathname === '/api/admin/columns' && request.method === 'POST') return await saveColumn(request, response, database)
    const columnDelete = pathname.match(/^\/api\/admin\/columns\/([^/]+)\/delete$/); if (columnDelete && request.method === 'POST') return deleteColumn(request, response, database, columnDelete[1])
    if (pathname === '/api/admin/points' && request.method === 'GET') return listPoints(request, response, database)
    if (pathname === '/api/admin/points' && request.method === 'POST') return await savePoint(request, response, database)
    const pointStatus = pathname.match(/^\/api\/admin\/points\/([^/]+)\/(verify|archive)$/); if (pointStatus && request.method === 'POST') return changeCatalogStatus(request, response, database, 'point', pointStatus[1], pointStatus[2])
    if (pathname === '/api/admin/problems' && request.method === 'GET') return listProblems(request, response, database)
    if (pathname === '/api/admin/problems' && request.method === 'POST') return await saveProblem(request, response, database)
    const problemStatus = pathname.match(/^\/api\/admin\/problems\/([^/]+)\/(verify|archive)$/); if (problemStatus && request.method === 'POST') return changeCatalogStatus(request, response, database, 'problem', problemStatus[1], problemStatus[2])
    if (pathname === '/api/admin/logs' && request.method === 'GET') return listLogs(request, response, database)
    if (pathname === '/api/admin/export' && request.method === 'GET') return exportData(request, response, database)
    if (pathname === '/api/admin/import-docx' && request.method === 'POST') return await importDocx(request, response, database, url)
    if (pathname === '/api/admin/article-sources' && request.method === 'GET') return sourceStatus(request, response, database)
    if (pathname.startsWith('/api/admin/article-sources/') && request.method === 'GET') return sourceCandidates(request, response, database, pathname, url)
    if (pathname.startsWith('/api/admin/article-sources/') && request.method === 'POST') return await sourceAction(request, response, database, pathname, url)
    if (pathname === '/api/upload' && request.method === 'POST') return await saveUpload(request, response, database, url)
    if (pathname.startsWith('/media/') && request.method === 'GET') return serveMedia(response, pathname)
    if (pathname === '/api/image-proxy' && request.method === 'GET') return imageProxy(response, url)
    if (pathname === '/admin') { response.writeHead(308, { Location: '/admin/' }); return response.end() }
    return serveStatic(response, pathname.startsWith('/admin/') ? pathname : pathname || '/')
  } catch (error) { console.error('[server]', error); if (!response.headersSent) send(response, 500, { error: '服务器内部错误' }) } finally { closeDb(database) }
}

async function setupAdmin(request, response, database) { const body = await readJson(request), username = asText(body.username), password = String(body.password || ''); if (one(database, 'SELECT COUNT(*) AS count FROM admin_users').count) return send(response, 409, { error: '管理员已经创建' }); if (!/^[A-Za-z0-9_.-]{3,}$/.test(username) || password.length < 8) return send(response, 422, { error: '用户名至少3位，密码至少8位' }); const id = `ADM-${crypto.randomUUID()}`, salt = crypto.randomBytes(16).toString('hex'); run(database, 'INSERT INTO admin_users VALUES(?,?,?,?,?,?)', [id, username, hashPassword(password, salt), salt, now(), null]); run(database, 'INSERT INTO admin_user_access VALUES(?,?,?,?)', [id, 'super_admin', now(), now()]); const issued = issueSession(database, id); audit(database, id, 'setup', 'admin_user', id); setCookie(response, SESSION_COOKIE, issued.token); return send(response, 201, { ok: true, username, csrfToken: issued.csrf }) }
async function login(request, response, database) { const body = await readJson(request), username = asText(body.username), password = String(body.password || ''), user = one(database, 'SELECT * FROM admin_users WHERE username=?', [username]); if (!user || !crypto.timingSafeEqual(Buffer.from(user.password_hash), Buffer.from(hashPassword(password, user.password_salt)))) return send(response, 401, { error: '用户名或密码不正确' }); const issued = issueSession(database, user.id); run(database, 'UPDATE admin_users SET last_login_at=? WHERE id=?', [now(), user.id]); audit(database, user.id, 'login', 'admin_user', user.id); setCookie(response, SESSION_COOKIE, issued.token); return send(response, 200, { ok: true, username, csrfToken: issued.csrf }) }
function logout(request, response, database) { const current = requireSession(database, request, response, true); if (!current) return; run(database, 'DELETE FROM admin_sessions WHERE token_hash=?', [sha256(cookiesFrom(request)[SESSION_COOKIE])]); audit(database, current.user_id, 'logout', 'admin_user', current.user_id); setCookie(response, SESSION_COOKIE, '', 0); return send(response, 200, { ok: true }) }

function listContents(request, response, database) { const current = requireSession(database, request, response); if (!current) return; const values = all(database, 'SELECT payload_json,status,version,updated_at,published_at FROM admin_contents ORDER BY updated_at DESC').map(row => { const item = normalizeContent(JSON.parse(row.payload_json)); Object.assign(item, { status: row.status, version: row.version, updatedAt: row.updated_at, publishedAt: row.published_at, contentHtml: '', casesHtml: '', sourceText: '', sourceNotes: '' }); return withRelations(database, item) }); return send(response, 200, { contents: values }) }
function getContent(request, response, database, id) { if (!requireSession(database, request, response)) return; const row = one(database, 'SELECT payload_json,status,version,updated_at,published_at FROM admin_contents WHERE id=?', [id]); if (!row) return send(response, 404, { error: '内容不存在' }); const item = normalizeContent(JSON.parse(row.payload_json)); Object.assign(item, { status: row.status, version: row.version, updatedAt: row.updated_at, publishedAt: row.published_at }); return send(response, 200, { content: withRelations(database, item) }) }
async function saveContent(request, response, database) { const raw = (await readJson(request)).content || {}, current = requireSession(database, request, response, true, raw.type === 'article' ? 'articles.write' : 'methods.write'); if (!current) return; const content = normalizeContent(raw); if (!content.id) return send(response, 400, { error: '内容格式不正确' }); const previous = one(database, 'SELECT version FROM admin_contents WHERE id=?', [content.id]), missing = validateContent(content), status = missing.length ? 'draft' : 'ready', version = (previous?.version || 0) + 1, stamp = now(); content.status = status; content.updatedAt = stamp; content.version = version; database.exec('BEGIN'); try { if (previous) run(database, 'UPDATE admin_contents SET title=?,method_name=?,status=?,payload_json=?,updated_at=?,version=? WHERE id=?', [content.title, content.methodName || '', status, json(content), stamp, version, content.id]); else run(database, 'INSERT INTO admin_contents(id,title,method_name,status,payload_json,created_at,updated_at,version) VALUES(?,?,?,?,?,?,?,?)', [content.id, content.title, content.methodName || '', status, json(content), stamp, stamp, version]); run(database, 'DELETE FROM content_point_links WHERE content_id=?', [content.id]); for (const [index, link] of content.pointLinks.entries()) run(database, 'INSERT INTO content_point_links(content_id,point_id,sort_order,instruction) VALUES(?,?,?,?)', [content.id, asText(link.pointId), index, asText(link.instruction)]); run(database, 'DELETE FROM problem_content_links WHERE content_id=?', [content.id]); for (const [index, link] of content.problemLinks.entries()) run(database, 'INSERT INTO problem_content_links(problem_id,content_id,evidence_type,evidence_text,sort_order) VALUES(?,?,?,?,?)', [asText(link.problemId), content.id, ['direct', 'case', 'author', 'pending'].includes(link.evidenceType) ? link.evidenceType : 'pending', asText(link.evidenceText), index]); audit(database, current.user_id, 'save', 'content', content.id, { status, version }); database.exec('COMMIT') } catch (error) { database.exec('ROLLBACK'); throw error } return send(response, 200, { ok: true, content: withRelations(database, content), missing }) }
function changeContentStatus(request, response, database, id, action) { const row = one(database, 'SELECT payload_json FROM admin_contents WHERE id=?', [id]); if (!row) return send(response, 404, { error: '内容不存在' }); const content = normalizeContent(JSON.parse(row.payload_json)), current = requireSession(database, request, response, true, action === 'publish' ? `${content.type === 'article' ? 'articles' : 'methods'}.publish` : `${content.type === 'article' ? 'articles' : 'methods'}.write`); if (!current) return; let status = action === 'publish' ? 'published' : action === 'withdraw' ? 'withdrawn' : action === 'archive' ? 'archived' : (validateContent(content).length ? 'draft' : 'ready'); if (action === 'publish') { const missing = validateContent(content); if (missing.length) return send(response, 422, { error: '内容尚未完成', missing }); if (content.type === 'article' && content.sourceKind === 'zibingziyi' && content.reviewStatus !== 'reviewed') return send(response, 422, { error: '导入文章尚未完成商业复核', missing: ['sourceReview'] }); const unverified = [...relationPoints(database, id).filter(item => item.point.status !== 'verified').map(item => item.point.name), ...relationProblems(database, id).filter(item => item.problem.status !== 'verified').map(item => item.problem.name)]; if (unverified.length) return send(response, 422, { error: `请先审核关联资料：${unverified.join('、')}` }); content.status = status; content.reviewConfirmed = true; content.reviewedBy = current.username; content.reviewedAt = now(); content.publishedAt = now() } else content.status = status; run(database, 'UPDATE admin_contents SET status=?,payload_json=?,updated_at=?,published_at=?,withdrawn_at=? WHERE id=?', [status, json(content), now(), status === 'published' ? now() : null, ['withdrawn', 'archived'].includes(status) ? now() : null, id]); audit(database, current.user_id, action, 'content', id, { status }); return send(response, 200, { ok: true, content: withRelations(database, content) }) }

function listColumns(request, response, database) { if (!requireSession(database, request, response, false, 'columns.manage')) return; return send(response, 200, { columns: all(database, 'SELECT * FROM anthology_columns ORDER BY sort_order,name') }) }
async function saveColumn(request, response, database) { const value = (await readJson(request)).column || {}, current = requireSession(database, request, response, true, 'columns.manage'); if (!current) return; const id = asText(value.id) || `COL-${crypto.randomUUID().slice(0, 12).toUpperCase()}`, name = asText(value.name), color = /^#[0-9A-Fa-f]{6}$/.test(value.color || '') ? value.color : '#E8EEE9'; if (!name) return send(response, 400, { error: '请填写专栏名称' }); const stamp = now(); if (one(database, 'SELECT id FROM anthology_columns WHERE id=?', [id])) run(database, 'UPDATE anthology_columns SET name=?,description=?,color=?,sort_order=?,status=?,updated_at=? WHERE id=?', [name, asText(value.description), color, Number(value.sort_order) || 0, value.status === 'hidden' ? 'hidden' : 'visible', stamp, id]); else run(database, 'INSERT INTO anthology_columns VALUES(?,?,?,?,?,?,?,?)', [id, name, asText(value.description), color, Number(value.sort_order) || 0, value.status === 'hidden' ? 'hidden' : 'visible', stamp, stamp]); audit(database, current.user_id, 'save', 'column', id, { name }); return send(response, 200, { ok: true, column: { ...value, id, name, color } }) }
function deleteColumn(request, response, database, id) { const current = requireSession(database, request, response, true, 'columns.manage'); if (!current) return; if (!one(database, 'SELECT id FROM anthology_columns WHERE id=?', [id])) return send(response, 404, { error: '专栏不存在' }); const linked = all(database, "SELECT id,payload_json FROM admin_contents WHERE json_extract(payload_json,'$.columnId')=?", [id]); linked.forEach(row => { const content = JSON.parse(row.payload_json); content.columnId = ''; content.columnName = ''; run(database, 'UPDATE admin_contents SET payload_json=?,updated_at=?,version=version+1 WHERE id=?', [json(content), now(), row.id]) }); run(database, 'DELETE FROM anthology_columns WHERE id=?', [id]); audit(database, current.user_id, 'delete', 'column', id, { detachedArticles: linked.length }); return send(response, 200, { ok: true, detachedArticles: linked.length }) }

function listPoints(request, response, database) { if (!requireSession(database, request, response, false, 'points.read')) return; return send(response, 200, { points: all(database, 'SELECT payload_json,status,version,updated_at,verified_at FROM admin_points ORDER BY updated_at DESC').map(row => ({ ...normalizePoint(JSON.parse(row.payload_json)), status: row.status, version: row.version, updatedAt: row.updated_at, verifiedAt: row.verified_at })) }) }
async function savePoint(request, response, database) { const point = normalizePoint((await readJson(request)).point), current = requireSession(database, request, response, true, 'points.write'); if (!current) return; if (!point.id) return send(response, 400, { error: '穴位格式不正确' }); const previous = one(database, 'SELECT version FROM admin_points WHERE id=?', [point.id]), stamp = now(), version = (previous?.version || 0) + 1; point.status = 'draft'; point.updatedAt = stamp; point.version = version; if (previous) run(database, 'UPDATE admin_points SET name=?,body_area_id=?,status=?,payload_json=?,updated_at=?,version=? WHERE id=?', [point.name, point.bodyAreaId, 'draft', json(point), stamp, version, point.id]); else run(database, 'INSERT INTO admin_points(id,name,body_area_id,status,payload_json,created_at,updated_at,version) VALUES(?,?,?,?,?,?,?,?)', [point.id, point.name, point.bodyAreaId, 'draft', json(point), stamp, stamp, version]); audit(database, current.user_id, 'save', 'point', point.id, { status: 'draft', version }); return send(response, 200, { ok: true, point, missing: validatePoint(point) }) }
function listProblems(request, response, database) { if (!requireSession(database, request, response, false, 'problems.read')) return; const problems = all(database, 'SELECT payload_json,status,version,updated_at,verified_at FROM admin_problems ORDER BY updated_at DESC').map(row => ({ ...normalizeProblem(JSON.parse(row.payload_json)), status: row.status, version: row.version, updatedAt: row.updated_at, verifiedAt: row.verified_at })); problems.forEach(problem => { problem.methodLinks = all(database, 'SELECT c.id,c.payload_json,l.evidence_type,l.evidence_text,l.sort_order,c.status FROM problem_content_links l JOIN admin_contents c ON c.id=l.content_id WHERE l.problem_id=? ORDER BY l.sort_order,c.title', [problem.id]).map(link => ({ contentId: link.id, order: link.sort_order, evidenceType: link.evidence_type, evidenceText: link.evidence_text, method: { ...normalizeContent(JSON.parse(link.payload_json)), status: link.status } })) }); return send(response, 200, { problems }) }
async function saveProblem(request, response, database) { const problem = normalizeProblem((await readJson(request)).problem), current = requireSession(database, request, response, true, 'problems.write'); if (!current) return; if (!problem.id) return send(response, 400, { error: '问题格式不正确' }); const previous = one(database, 'SELECT version FROM admin_problems WHERE id=?', [problem.id]), stamp = now(), version = (previous?.version || 0) + 1; problem.status = 'draft'; problem.updatedAt = stamp; problem.version = version; database.exec('BEGIN'); try { if (previous) run(database, 'UPDATE admin_problems SET name=?,status=?,payload_json=?,updated_at=?,version=? WHERE id=?', [problem.name, 'draft', json(problem), stamp, version, problem.id]); else run(database, 'INSERT INTO admin_problems(id,name,status,payload_json,created_at,updated_at,version) VALUES(?,?,?,?,?,?,?)', [problem.id, problem.name, 'draft', json(problem), stamp, stamp, version]); run(database, 'DELETE FROM problem_content_links WHERE problem_id=?', [problem.id]); for (const [index, link] of problem.methodLinks.entries()) run(database, 'INSERT INTO problem_content_links(problem_id,content_id,evidence_type,evidence_text,sort_order) VALUES(?,?,?,?,?)', [problem.id, asText(link.contentId), ['direct', 'case', 'author', 'pending'].includes(link.evidenceType) ? link.evidenceType : 'pending', asText(link.evidenceText), index]); audit(database, current.user_id, 'save', 'problem', problem.id, { status: 'draft', version }); database.exec('COMMIT') } catch (error) { database.exec('ROLLBACK'); throw error } return send(response, 200, { ok: true, problem, missing: validateProblem(problem) }) }
function changeCatalogStatus(request, response, database, kind, id, action) { const table = kind === 'point' ? 'admin_points' : 'admin_problems', current = requireSession(database, request, response, true, `${kind === 'point' ? 'points' : 'problems'}.write`); if (!current) return; const row = one(database, `SELECT payload_json FROM ${table} WHERE id=?`, [id]); if (!row) return send(response, 404, { error: `${kind === 'point' ? '穴位' : '问题'}不存在` }); const value = kind === 'point' ? normalizePoint(JSON.parse(row.payload_json)) : normalizeProblem(JSON.parse(row.payload_json)), missing = kind === 'point' ? validatePoint(value) : validateProblem(value); if (action === 'verify' && missing.length) return send(response, 422, { error: '资料尚未完成', missing }); const status = action === 'verify' ? 'verified' : 'archived'; value.status = status; value.verifiedAt = action === 'verify' ? now() : null; run(database, `UPDATE ${table} SET status=?,payload_json=?,updated_at=?,verified_at=? WHERE id=?`, [status, json(value), now(), value.verifiedAt, id]); audit(database, current.user_id, action, kind, id, { status }); return send(response, 200, { ok: true, [kind]: value }) }
function listLogs(request, response, database) { if (!requireSession(database, request, response, false, 'logs.read')) return; return send(response, 200, { logs: all(database, 'SELECT l.action,l.entity_type,l.entity_id,l.detail_json,l.created_at,u.username FROM admin_audit_logs l LEFT JOIN admin_users u ON u.id=l.user_id ORDER BY l.created_at DESC LIMIT 100') }) }
function exportData(request, response, database) { if (!requireSession(database, request, response, false, 'backup.export')) return; const body = Buffer.from(JSON.stringify({ exportedAt: now(), allContents: all(database, 'SELECT payload_json FROM admin_contents ORDER BY updated_at DESC').map(row => JSON.parse(row.payload_json)) }, null, 2)); response.writeHead(200, { 'Content-Type': 'application/json; charset=utf-8', 'Content-Disposition': 'attachment; filename="xiaoqingnang-backup.json"', 'Content-Length': body.length }); response.end(body) }

async function importDocx(request, response, database, url) { const current = requireSession(database, request, response, true, 'articles.write'); if (!current) return; const original = path.basename(url.searchParams.get('name') || 'article.docx'); if (!original.toLowerCase().endsWith('.docx')) return send(response, 415, { error: '目前只支持 .docx 文件' }); const body = await readBody(request, MAX_UPLOAD); if (!body.length) return send(response, 413, { error: 'Word 文件为空或超过120MB' }); let extracted; try { extracted = extractDocx(body, original) } catch (error) { console.error('[docx]', error); return send(response, 422, { error: '无法读取 Word 文件，请确认文件未损坏' }) } if (!extracted.html || extracted.plain.length < 20) return send(response, 422, { error: '没有从 Word 中读取到有效正文' }); const title = path.basename(original, '.docx').replace(/^\d{4}-\d{2}-\d{2}_/, '').trim(); const draft = normalizeContent({ id: `CNT-${crypto.randomUUID().replaceAll('-', '').slice(0, 16).toUpperCase()}`, type: 'article', title, summary: summaryFrom(extracted.plain), contentHtml: extracted.html, sourceTitle: title, sourcePlatform: 'Word 导入', sourceText: `原始 Word 文件：${original}`, sourceNotes: '由后台导入，请在发布前校对正文、图片、专栏与阅读边界。', outsideScope: '本文用于资料阅读，不作为诊断、处方或自行操作指引。', columnName: '青囊选读', status: 'draft' }); audit(database, current.user_id, 'import', 'article', draft.id, { name: original, bytes: body.length }); return send(response, 200, { ok: true, content: draft }) }

function sourceStatus(request, response, database) { if (!requireSession(database, request, response, false, 'source.manage')) return; return send(response, 200, { total: one(database, 'SELECT COUNT(*) AS count FROM anthology_source_links WHERE source_key=?', ['zibingziyi']).count, candidates: one(database, "SELECT COUNT(*) AS count FROM anthology_source_candidates WHERE source_key=? AND screening_status IN ('candidate','selected')", ['zibingziyi']).count }) }
function sourceCandidates(request, response, database, pathname, url) { if (!requireSession(database, request, response, false, 'source.manage')) return; const match = pathname.match(/^\/api\/admin\/article-sources\/([^/]+)\/candidates$/); if (!match) return send(response, 404, { error: '接口不存在' }); const where = ['source_key=?'], args = [match[1]], status = url.searchParams.get('status'), type = url.searchParams.get('suggestedType'), q = url.searchParams.get('q') || ''; if (status) { where.push('screening_status=?'); args.push(status) } if (type) { where.push('suggested_type=?'); args.push(type) } if (q) { where.push('(title LIKE ? OR summary LIKE ?)'); args.push(`%${q}%`, `%${q}%`) } return send(response, 200, { candidates: all(database, `SELECT * FROM anthology_source_candidates WHERE ${where.join(' AND ')} ORDER BY scanned_at DESC LIMIT 500`, args).map(row => ({ ...row, screening_flags: JSON.parse(row.screening_flags || '[]') })) }) }
async function sourceJson(pathname) { if (!SOURCE_API_BASE) throw new Error('尚未配置自病自医数据源地址，请设置 XQN_ZIBINGZIYI_API'); const result = await fetch(`${SOURCE_API_BASE}${pathname}`, { headers: { Accept: 'application/json' } }); if (!result.ok) throw new Error(`来源服务返回 ${result.status}`); return result.json() }
function sourceItem(item) { return { externalId: asText(item.id || item.external_id), title: asText(item.title), summary: asText(item.summary), category: asText(item.category_name || item.category), sourceUrl: asText(item.url || item.source_url), publishedAt: asText(item.updated_at || item.published_at), suggestedType: ['article', 'skill', 'problem'].includes(item.suggested_type) ? item.suggested_type : 'article' } }
async function scanSource(request, response, database, sourceKey) { const current = requireSession(database, request, response, true, 'source.manage'); if (!current) return; let page = 1, received = 0, candidates = 0, promotionFlags = 0, totalPages = 1; try { do { const payload = await sourceJson(`/articles?page=${page}&pageSize=50`), values = Array.isArray(payload.data) ? payload.data : Array.isArray(payload.articles) ? payload.articles : []; totalPages = Number(payload.pagination?.totalPages || 1); for (const raw of values) { const item = sourceItem(raw); if (!item.externalId) continue; const flags = promotionPattern.test(`${item.title} ${item.summary}`) ? ['标题或摘要含商业痕迹'] : []; run(database, `INSERT INTO anthology_source_candidates(source_key,external_id,title,summary,category,source_url,published_at,suggested_type,screening_flags,screening_status,scanned_at) VALUES(?,?,?,?,?,?,?,?,?,?,?) ON CONFLICT(source_key,external_id) DO UPDATE SET title=excluded.title,summary=excluded.summary,category=excluded.category,source_url=excluded.source_url,published_at=excluded.published_at,suggested_type=excluded.suggested_type,screening_flags=excluded.screening_flags,scanned_at=excluded.scanned_at`, [sourceKey, item.externalId, item.title, item.summary, item.category, item.sourceUrl, item.publishedAt, item.suggestedType, json(flags), one(database, 'SELECT screening_status FROM anthology_source_candidates WHERE source_key=? AND external_id=?', [sourceKey, item.externalId])?.screening_status || 'candidate', now()]); received++; candidates++; if (flags.length) promotionFlags++ } page++ } while (page <= totalPages); audit(database, current.user_id, 'scan', 'source', sourceKey, { received, candidates, promotionFlags }); return send(response, 200, { received, candidates, promotionFlags }) } catch (error) { return send(response, 502, { error: error.message || '来源扫描失败' }) } }
async function syncSource(request, response, database, sourceKey, selectedOnly = false, limit = 100, offset = 0) { const current = requireSession(database, request, response, true, 'source.manage'); if (!current) return; if (!SOURCE_API_BASE) return send(response, 503, { error: '尚未配置自病自医数据源地址，请设置 XQN_ZIBINGZIYI_API' }); const where = selectedOnly ? "source_key=? AND screening_status='selected'" : "source_key=? AND screening_status IN ('candidate','selected','imported')", candidates = all(database, `SELECT * FROM anthology_source_candidates WHERE ${where} ORDER BY scanned_at DESC LIMIT ? OFFSET ?`, [sourceKey, Math.min(100, Math.max(1, limit)), Math.max(0, offset)]); const result = { received: candidates.length, created: 0, updated: 0, unchanged: 0, flagged: 0, skipped: 0 }; for (const candidate of candidates) { try { const payload = await sourceJson(`/articles/${encodeURIComponent(candidate.external_id)}`), raw = payload.data || payload.article || payload; const sourceHtml = asText(raw.content || raw.contentHtml || raw.body); if (!sourceHtml) { result.skipped++; continue } const cleaned = cleanImportedHtml(sourceHtml); if (!stripTags(cleaned.html)) { result.skipped++; continue } const sourceHash = sha256(JSON.stringify(raw)); const link = one(database, 'SELECT content_id,raw_hash FROM anthology_source_links WHERE source_key=? AND external_id=?', [sourceKey, candidate.external_id]); if (link?.raw_hash === sourceHash) { result.unchanged++; continue } const contentId = link?.content_id || `ZBYZ-${candidate.external_id}`, existing = one(database, 'SELECT payload_json,status FROM admin_contents WHERE id=?', [contentId]), previous = existing ? normalizeContent(JSON.parse(existing.payload_json)) : null, flags = [...new Set(cleaned.flags)], content = normalizeContent({ ...(previous || {}), id: contentId, type: 'article', title: asText(raw.title || candidate.title), summary: asText(raw.summary || candidate.summary) || summaryFrom(stripTags(cleaned.html)), contentHtml: cleaned.html, columnName: asText(raw.category_name || candidate.category), sourceKind: sourceKey, sourceArticleId: candidate.external_id, sourceTitle: asText(raw.title || candidate.title), sourceAuthor: asText(raw.author || raw.source_author), sourcePlatform: '自病自医', sourceUrl: asText(raw.url || candidate.source_url), sourceText: `自病自医原文：${candidate.external_id}`, sourceNotes: '同步后请人工校对正文、图片和商业内容。', reviewStatus: flags.length ? 'needs_review' : 'clean', reviewFlags: flags, removedPromotions: cleaned.removed, status: previous?.status || 'draft', updatedAt: now() }); const stamp = now(); if (existing) run(database, 'UPDATE admin_contents SET title=?,method_name=?,status=?,payload_json=?,updated_at=?,version=version+1 WHERE id=?', [content.title, '', content.status, json(content), stamp, contentId]); else run(database, 'INSERT INTO admin_contents(id,title,method_name,status,payload_json,created_at,updated_at,version) VALUES(?,?,?,?,?,?,?,?)', [contentId, content.title, '', 'draft', json(content), stamp, stamp, 1]); run(database, `INSERT INTO anthology_source_links(source_key,external_id,content_id,source_updated_at,raw_hash,synced_at,source_missing) VALUES(?,?,?,?,?,?,0) ON CONFLICT(source_key,external_id) DO UPDATE SET content_id=excluded.content_id,source_updated_at=excluded.source_updated_at,raw_hash=excluded.raw_hash,synced_at=excluded.synced_at,source_missing=0`, [sourceKey, candidate.external_id, contentId, asText(raw.updated_at || candidate.published_at), sourceHash, stamp]); run(database, 'UPDATE anthology_source_candidates SET screening_status=? WHERE source_key=? AND external_id=?', ['imported', sourceKey, candidate.external_id]); if (flags.length) result.flagged++; if (existing) result.updated++; else result.created++ } catch (error) { result.skipped++ } } audit(database, current.user_id, 'sync', 'source', sourceKey, result); return send(response, 200, result) }
async function sourceAction(request, response, database, pathname, url) { const candidate = pathname.match(/^\/api\/admin\/article-sources\/([^/]+)\/candidates\/([^/]+)$/); if (candidate) { const current = requireSession(database, request, response, true, 'source.manage'); if (!current) return; const body = await readJson(request), status = ['selected', 'ignored'].includes(body.status) ? body.status : 'candidate'; run(database, 'UPDATE anthology_source_candidates SET screening_status=? WHERE source_key=? AND external_id=?', [status, candidate[1], candidate[2]]); audit(database, current.user_id, 'save', 'source_candidate', candidate[2], { status }); return send(response, 200, { ok: true }) } const match = pathname.match(/^\/api\/admin\/article-sources\/([^/]+)\/(scan|sync|import-selected)$/); if (!match) return send(response, 404, { error: '接口不存在' }); if (match[2] === 'scan') return scanSource(request, response, database, match[1]); if (match[2] === 'sync') return syncSource(request, response, database, match[1]); return syncSource(request, response, database, match[1], true, Number(url.searchParams.get('limit') || 100), Number(url.searchParams.get('offset') || 0)) }
async function saveUpload(request, response, database, url) { const current = requireSession(database, request, response, true, 'articles.write'); if (!current) return; const type = String(request.headers['content-type'] || '').split(';')[0]; if (!type.startsWith('image/') && !type.startsWith('video/')) return send(response, 415, { error: '只支持图片或视频' }); const body = await readBody(request, MAX_UPLOAD), suffix = path.extname(url.searchParams.get('name') || 'media').toLowerCase().slice(0, 10), filename = `${crypto.randomUUID().replaceAll('-', '')}${suffix}`; fs.mkdirSync(UPLOAD_DIR, { recursive: true }); fs.writeFileSync(path.join(UPLOAD_DIR, filename), body); audit(database, current.user_id, 'upload', 'media', filename, { contentType: type, bytes: body.length }); return send(response, 200, { ok: true, url: `/media/${filename}` }) }
function serveMedia(response, pathname) { const target = path.join(UPLOAD_DIR, path.basename(pathname.slice('/media/'.length))); if (!fs.existsSync(target)) return send(response, 404, { error: '素材不存在' }); const body = fs.readFileSync(target); response.writeHead(200, { 'Content-Type': MIME[path.extname(target).toLowerCase()] || 'application/octet-stream', 'Content-Length': body.length, 'Cache-Control': 'public, max-age=86400' }); response.end(body) }
async function imageProxy(response, url) { const target = url.searchParams.get('url') || ''; let parsed; try { parsed = new URL(target) } catch { return send(response, 400, { error: '不支持的图片地址' }) } if (parsed.protocol !== 'https:' || !['zengshiwuyu.cn', 'zibingziyi.zengshiwuyu.cn'].includes(parsed.hostname)) return send(response, 400, { error: '不支持的图片地址' }); try { const result = await fetch(target); if (!result.ok) return send(response, 502, { error: '原图暂时无法读取' }); const body = Buffer.from(await result.arrayBuffer()), type = result.headers.get('content-type') || 'image/jpeg'; if (!type.startsWith('image/')) return send(response, 415, { error: '原地址不是图片' }); response.writeHead(200, { 'Content-Type': type, 'Content-Length': body.length, 'Cache-Control': 'public, max-age=86400' }); response.end(body) } catch { send(response, 502, { error: '原图暂时无法读取' }) } }
function serveStatic(response, pathname) { if (!fs.existsSync(WEB_DIR)) return send(response, 503, { error: 'Web 产物尚未生成，请先在 HBuilderX 发行到 Web' }); let target = path.resolve(WEB_DIR, pathname.replace(/^\/+/, '') || 'index.html'); if (!target.startsWith(path.resolve(WEB_DIR))) return send(response, 404, { error: '资源不存在' }); if (!fs.existsSync(target) || fs.statSync(target).isDirectory()) target = path.join(WEB_DIR, 'index.html'); const body = fs.readFileSync(target); response.writeHead(200, { 'Content-Type': MIME[path.extname(target).toLowerCase()] || 'application/octet-stream', 'Content-Length': body.length, 'X-Content-Type-Options': 'nosniff', 'X-Frame-Options': 'DENY', 'Referrer-Policy': 'same-origin', 'Cache-Control': pathname.startsWith('/admin/') ? 'no-store' : 'no-cache' }); response.end(body) }

